CREATE TABLE "User" ("id" TEXT NOT NULL, "googleId" TEXT, "email" TEXT NOT NULL, "name" TEXT NOT NULL, "avatar" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Sender" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "email" TEXT NOT NULL, "name" TEXT NOT NULL, "smtpHost" TEXT NOT NULL, "smtpPort" INTEGER NOT NULL, "smtpUser" TEXT NOT NULL, "smtpPass" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Sender_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Campaign" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "subject" TEXT NOT NULL, "body" TEXT NOT NULL, "startAt" TIMESTAMP(3) NOT NULL, "delayMs" INTEGER NOT NULL, "hourlyLimit" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Campaign_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Email" ("id" TEXT NOT NULL, "campaignId" TEXT NOT NULL, "toEmail" TEXT NOT NULL, "subject" TEXT NOT NULL, "body" TEXT NOT NULL, "senderId" TEXT NOT NULL, "scheduledAt" TIMESTAMP(3) NOT NULL, "sentAt" TIMESTAMP(3), "status" TEXT NOT NULL DEFAULT 'scheduled', "processingAt" TIMESTAMP(3), "lastError" TEXT, CONSTRAINT "Email_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EmailEvent" ("id" TEXT NOT NULL, "emailId" TEXT NOT NULL, "type" TEXT NOT NULL, "payload" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EmailEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SlackConnection" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "accessToken" TEXT, "webhookUrl" TEXT NOT NULL, "channel" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SlackConnection_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_googleId_key" ON "User"("googleId");
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Sender_userId_email_key" ON "Sender"("userId","email");
CREATE UNIQUE INDEX "Email_campaignId_toEmail_key" ON "Email"("campaignId","toEmail");
CREATE INDEX "Email_status_processingAt_idx" ON "Email"("status","processingAt");
CREATE INDEX "Email_scheduledAt_idx" ON "Email"("scheduledAt");
CREATE INDEX "EmailEvent_emailId_createdAt_idx" ON "EmailEvent"("emailId","createdAt");
CREATE UNIQUE INDEX "SlackConnection_userId_key" ON "SlackConnection"("userId");
ALTER TABLE "Sender" ADD CONSTRAINT "Sender_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Campaign" ADD CONSTRAINT "Campaign_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Email" ADD CONSTRAINT "Email_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Email" ADD CONSTRAINT "Email_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "Sender"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "EmailEvent" ADD CONSTRAINT "EmailEvent_emailId_fkey" FOREIGN KEY ("emailId") REFERENCES "Email"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SlackConnection" ADD CONSTRAINT "SlackConnection_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
